int massage(int *nums, int numsSize) {
  int prev = 0, cur = 0;
  for (int i = 0; i < numsSize; i++) {
    int take = prev + nums[i];
    int skip = cur;
    prev = cur;
    cur = take > skip ? take : skip;
  }
  return cur;
}

class Solution {
public:
  int massage(vector<int> &nums) {
    int prev = 0, cur = 0;
    for (int x : nums) {
      int tmp = cur;
      cur = max(cur, prev + x);
      prev = tmp;
    }
    return cur;
  }
};

func massage(nums []int) int {
	prev, cur := 0, 0
	for _, x := range nums {
		take, skip := prev+x, cur
		prev = cur
		if take > skip {
			cur = take
		} else {
			cur = skip
		}
	}
	return cur
}

class Solution {
  public int massage(int[] nums) {
    int prev = 0, cur = 0;
    for (int x : nums) {
      int tmp = cur;
      cur = Math.max(cur, prev + x);
      prev = tmp;
    }
    return cur;
  }
}

class Solution:
    def massage(self, nums: List[int]) -> int:
        prev = cur = 0
        for x in nums:
            prev, cur = cur, max(cur, prev + x)
        return cur

impl Solution {
  pub fn massage(nums: Vec<i32>) -> i32 {
    let (mut prev, mut cur) = (0, 0);
    for x in nums {
      let tmp = cur;
      cur = cur.max(prev + x);
      prev = tmp;
    }
    cur
  }
}

const massage = (nums: number[]): number => {
  let prev = 0;
  let cur = 0;
  for (const x of nums) {
    const tmp = cur;
    cur = Math.max(cur, prev + x);
    prev = tmp;
  }
  return cur;
};
